        <p>{dataL?.list[0].weather[0].main}</p>
      </div>
      <div className="eachTemp">
      <p>{dataL?.list[1].dt_txt}</p>
        {temp === "C" ? (
          <p>{Math.trunc(kelvinToCelsius(dataL?.list[1].main.temp))} °C</p>
        ) : (
          <p>{Math.trunc(kelvinToFar(dataL?.list[1].main.temp))} °F</p>
        )}
